                    const heightPercent = maxMonthlyAmount > 0 && hasData ? Math.max(14, Math.round((m.amount / maxMonthlyAmount) * 100)) : 0;
                    const isCurrentMonth = idx === (feeStats?.monthlyTrend.length || 0) - 1;
